"""Policy texts (Arabic). Every clause of the reference site's terms is covered here in our own wording,
   adapted to Mervat Soror's business and Egyptian law. Placeholders in [brackets] must be filled before launch.
   Must be reviewed by a lawyer before going live."""

BIZ = "[الاسم التجاري / اسم المنشأة]"
CR = "[رقم السجل التجاري]"
TAX = "[رقم البطاقة الضريبية]"
ADDR = "[العنوان: المدينة، مصر]"
MAIL = "support@mervatsoror.com"
PHONE = "+20 109 529 2748"
SITE = "mervatsoror.com"

LEGAL = [
("terms.html", "الشروط والأحكام", "شروط استخدام منصة د. مرفت سرور، حماية الحساب، الاستخدام المسموح للأدوات، الدفع، عدم الاسترداد، والإجراءات عند إساءة الاستخدام.", [
 ("١) التعريفات", f"<ul><li><b>الموقع / المنصة:</b> {SITE} وكل الخدمات الرقمية المرتبطة به، ويديره {BIZ}، سجل تجاري {CR}، بطاقة ضريبية {TAX}.</li><li><b>المشترك:</b> كل شخص دفع مقابل أداة أو كورس أو برنامج أو جلسة على المنصة.</li><li><b>الزائر:</b> كل شخص يتصفح الموقع دون شراء.</li><li><b>الأدوات / المحتوى:</b> كل ما يُقدَّم عبر المنصة من تسجيلات صوتية ومرئية، وتمارين Decoding وPriming، وكورسات، ولقاءات مباشرة، وكتب إلكترونية، وملفات ونصوص وصور، وأي مادة تعليمية أخرى.</li><li><b>الاشتراك:</b> برنامج استيقظ VIP الشهري أو السنوي، أو أي اشتراك متجدد تعلنه المنصة.</li></ul>"),
 ("٢) قبول الشروط", "<p>باستخدامك للموقع أو إنشاء حساب أو شراء أي أداة أو الاشتراك في أي برنامج، فأنت توافق صراحةً على الالتزام بهذه الشروط، وب<a href='refund.html'>سياسة الاسترداد والإلغاء</a>، و<a href='privacy.html'>سياسة الخصوصية</a>، و<a href='delivery.html'>سياسة تقديم الخدمة</a>.</p>"),
 ("٣) حق المنصة في تعديل السياسات", "<ul><li>يحق لإدارة المنصة تعديل أو تحديث أي بند من هذه الشروط في أي وقت.</li><li>تُنشر التعديلات على هذه الصفحة مع تاريخ آخر تحديث، ويُعد استمرارك في استخدام الموقع بعد النشر قبولاً منك لها.</li><li>قد تُطبّق التعديلات على الاشتراكات الحالية أو على الاشتراكات الجديدة فقط بحسب ما تقرره الإدارة، ويُوضّح ذلك عند الإعلان عن التعديل.</li></ul>"),
 ("٤) التسجيل وحماية الحساب", "<ul><li>يلتزم المشترك بتقديم بيانات صحيحة وكاملة (الاسم الكامل، البريد الإلكتروني، الدولة، رقم الهاتف) وتحديثها عند تغييرها.</li><li>يُمنع مشاركة بيانات الدخول (البريد الإلكتروني وكلمة المرور) مع أي شخص مهما كانت صلته بك.</li><li><b>لا يُسمح بتسجيل الدخول من أكثر من جهازين في الوقت نفسه</b> لكل حساب، ما لم توافق الإدارة كتابياً على خلاف ذلك.</li><li>يُمنع استخدام الحساب من قِبل الأصدقاء أو زملاء العمل أو الشركاء أو المدربين الآخرين أو المتدربين أو أي مؤسسة أو طرف ثالث.</li><li><b>بشكل صريح:</b> لا يجوز مشاركة الأدوات أو بيانات الدخول مع أي فرد من العائلة، بمن فيهم الوالدان والزوج أو الزوجة والأبناء والإخوة والأقارب والجيران.</li><li>عند ثبوت مشاركة بيانات الدخول أو نقل المحتوى لأي طرف ثالث، يحق للإدارة اتخاذ إجراءات تشمل دون حصر: تعليق الحساب، وإلغاء الاشتراك، والحظر النهائي، ومطالبة المتسبب بالتعويض عن الأضرار والخسائر.</li></ul>"),
 ("٥) الأدوات والاشتراكات: الاستخدام المسموح والممنوعات", "<p>كل الأدوات على المنصة مخصّصة للاستخدام الشخصي فقط من قِبل صاحب الحساب وداخل حسابه.</p><p><b>يُمنع منعاً باتاً:</b></p><ul><li><b>إعادة النشر:</b> رفع أو نشر أو بث أي أداة أو جزء منها على أي منصة عامة.</li><li><b>المشاركة مع العائلة أو الأصدقاء:</b> إرسال الأدوات أو مقاطع منها لأي شخص.</li><li><b>البيع أو التداول:</b> بيع أو تأجير أو عرض أو توزيع أي أداة للغير، بمقابل أو مجاناً.</li><li><b>التسجيل والنسخ:</b> تصوير الشاشة أو تسجيلها، أو تسجيل الصوت أو الفيديو، أو نسخ مقتطفات ونشرها.</li><li><b>التعديل والاستخدام التجاري:</b> تعديل الأدوات أو ترجمتها أو الاقتباس منها أو دمجها أو إعادة إنتاجها لاستخدام تجاري أو تدريبي دون إذن كتابي.</li><li><b>تدريب الآخرين:</b> استخدام المحتوى في تدريب أو تقديم جلسات لمجموعات مدفوعة أو مجانية دون إذن كتابي.</li><li><b>التوزيع داخل المجموعات:</b> نشر الأدوات أو روابطها في مجموعات واتساب أو تيليجرام أو فيسبوك أو قوائم بريدية.</li></ul><p><b>أمثلة توضيحية (وليست حصرية):</b></p><ul><li>لا يجوز إرسال رابط تمرين أو درس لقريب أو صديقة أو زميل.</li><li>لا يجوز تحميل أي تسجيل ثم رفعه على قناتك أو صفحتك.</li><li>لا يجوز تصوير جزء من تمرين ومشاركته في الستوري أو الريلز أو أي خاصية مشابهة.</li></ul>"),
 ("٦) سياسة الإهداء", "<p>إذا أردت إهداء أداة أو برنامج لشخص آخر، استخدم خيار «إهداء هذه الأداة» أو تواصل معنا ليُفتح المحتوى في حساب المُهدى إليه باسمه وبريده. لا يجوز إهداء أداة بمشاركة بيانات حسابك، ولا يمكن نقل أداة من حسابك إلى حساب آخر بعد فتحها.</p>"),
 ("٧) سياسة الدفع", f"<ul><li>كل الرسوم تُدفع مقدماً لإتمام الشراء أو الاشتراك.</li><li>وسائل الدفع المقبولة: البطاقات البنكية وميزة والمحافظ الإلكترونية وفوري والتقسيط داخل مصر عبر Paymob، والبطاقات الدولية عبر البنك الأهلي المصري، وPayPal، وأي وسيلة أخرى تعلنها المنصة رسمياً.</li><li>الأسعار بالجنيه المصري للمقيمين في مصر وبالدولار الأمريكي لباقي الدول، ويُحدَّد السعر حسب بلد الفاتورة. اختيار بلد غير صحيح للحصول على سعر مختلف يُعد مخالفة تُلغى بسببها العملية.</li><li>في حال الخصم المزدوج أو خطأ تقني في الدفع، تواصل فوراً مع الدعم على <span class='copyable'>{MAIL}</span> أو واتساب <span class='copyable'>{PHONE}</span> مع إرفاق إثبات الدفع.</li><li>أي رسوم بنكية أو رسوم تحويل عملة يفرضها بنكك يتحملها المشترك.</li><li>إذا كان المبلغ المسدد ناقصاً، لا يُفتح المحتوى إلا بعد إتمام المبلغ كاملاً.</li></ul>"),
 ("٨) عدم القابلية للاسترداد", "<p><b>نؤكد صراحةً:</b> لا يمكن استرداد المبالغ المدفوعة، ولا استبدال الأدوات أو الاشتراكات أو جزء منها، لأي سبب، بما في ذلك: الشراء عن طريق الخطأ، أو عدم قراءة وصف الأداة، أو عدم المتابعة خلال مدة الاشتراك، أو عدم تحقق الفائدة المتوقعة. الاستثناءات الوحيدة مذكورة في <a href='refund.html'>سياسة الاسترداد والإلغاء</a> (الخصم المزدوج، والخطأ التقني الذي لم يُحل، وإلغاء الجلسة من جهتنا).</p>"),
 ("٩) مدة الوصول إلى المحتوى", "<ul><li>الأدوات المشتراة منفصلة متاحة مدى الحياة ما دامت المنصة تعمل وما دام الحساب ملتزماً بهذه الشروط، ما لم يُذكر في وصف الأداة مدة وصول محددة.</li><li>محتوى برنامج استيقظ VIP متاح طوال مدة الاشتراك فقط، ويُحجب بعد انتهائها ما لم يُجدَّد.</li><li>يتحمل المشترك مسؤولية متابعة المحتوى خلال مدة الوصول المتاحة له.</li><li>لا تتحمل المنصة مسؤولية فقدان الوصول بسبب انقطاع خدمات خارجية خارجة عن إرادتها.</li></ul>"),
 ("١٠) مسؤولية المحتوى والنتائج", "<ul><li>المحتوى تعليمي وتدريبي في الوعي والتطوير الذاتي، و<b>ليس علاجاً طبياً أو نفسياً</b> ولا يغني عن استشارة الطبيب أو الأخصائي.</li><li>النتائج تختلف من شخص لآخر بحسب الالتزام والظروف، ولا نضمن نتيجة محددة.</li><li>لا تتحمل المنصة مسؤولية أي ضرر ناتج عن سوء فهم المحتوى أو تطبيقه بشكل خاطئ.</li><li>يُنصح باستشارة مختص (طبي أو نفسي أو قانوني) عند الحاجة قبل تطبيق أي ممارسة، خاصة للحوامل ومن لديهم حالات صحية.</li></ul>"),
 ("١١) إساءة الاستخدام والعواقب", "<p>عند ثبوت إساءة استخدام المحتوى أو مشاركته دون إذن، يحق للإدارة:</p><ul><li>تعطيل الحساب أو تعليقه فوراً.</li><li>إلغاء الاشتراك والأدوات دون أي تعويض مالي.</li><li>مطالبة المتسبب بالتعويض عن الأضرار.</li><li>اتخاذ الإجراءات القانونية والقضائية اللازمة.</li></ul><p>وتحتفظ الإدارة بحقها في اتخاذ أي إجراء آخر لحماية حقوق الملكية الفكرية والحقوق التجارية.</p>"),
 ("١٢) تعديل المحتوى أو إتاحته", "<p>تحتفظ المنصة بحق إيقاف أي أداة أو برنامج أو تعديله، أو تغيير مواعيد اللقاءات المباشرة أو منصة تقديمها، لاعتبارات تنظيمية أو تقنية. نبلغ المشتركين بالتغييرات الجوهرية بالبريد الإلكتروني أو بإشعار داخل الحساب.</p>"),
 ("١٣) المسؤولية التقنية", "<ul><li>نعمل على توفير تجربة تقنية مستقرة، لكن لا نضمن خلوّ الخدمة تماماً من الأعطال المؤقتة.</li><li>لا نتحمل مسؤولية الانقطاع الناتج عن ظروف خارجة عن إرادتنا (مثل انقطاع الإنترنت أو أعطال مزوّدي الخدمة).</li><li>إذا واجهت مشكلة تقنية تمنعك من الوصول إلى المحتوى ولم تُحل، تواصل مع الدعم لتقييم حالتك.</li></ul>"),
 ("١٤) حقوق الملكية والإبلاغ عن المخالفات", f"<p>كل المحتوى والعلامة التجارية والشعار مملوك لـ د. مرفت سرور ومحمي بقانون حماية حقوق الملكية الفكرية المصري رقم ٨٢ لسنة ٢٠٠٢. إذا وجدت أدواتنا منشورة دون إذن، أو كنت صاحب حق وتعتقد أن محتوى على المنصة يخالف حقوقك، راسلنا على <span class='copyable'>{MAIL}</span> مع التفاصيل والإثباتات.</p>"),
 ("١٥) القانون المطبق وحل النزاعات", "<p>تخضع هذه الشروط وتُفسَّر وفق قوانين جمهورية مصر العربية، ومنها قانون حماية المستهلك رقم ١٨١ لسنة ٢٠١٨. عند أي نزاع نسعى أولاً للحل الودي، ثم تختص محاكم [المدينة] بالفصل فيه.</p>"),
 ("١٦) التواصل", f"<ul><li>الدعم الفني وخدمة العملاء: <span class='copyable'>{MAIL}</span></li><li>واتساب: <span class='copyable'>{PHONE}</span></li><li>للاستفسارات التجارية والتعاون: نفس البريد مع كتابة موضوع الرسالة.</li><li>العنوان: {ADDR}</li></ul>"),
]),
("privacy.html", "سياسة الخصوصية", "كيف تجمع منصة د. مرفت سرور بياناتك وتستخدمها وتحميها.", [
 ("١) من نحن", f"<p>{BIZ} هو المسؤول عن معالجة بياناتك على {SITE}. نلتزم بحماية خصوصيتك وفق قانون حماية البيانات الشخصية المصري رقم ١٥١ لسنة ٢٠٢٠، وبالمبادئ الدولية لحماية البيانات لعملائنا خارج مصر.</p>"),
 ("٢) البيانات التي نجمعها", "<ul><li><b>بيانات الحساب:</b> الاسم الكامل، والبريد الإلكتروني، والدولة، ورقم الهاتف، وكلمة المرور (مشفّرة).</li><li><b>بيانات الطلبات:</b> الأدوات المشتراة، والمبالغ، وتاريخ الطلب، وبلد الفاتورة، ووسيلة الدفع المستخدمة (دون بيانات البطاقة).</li><li><b>بيانات الاستخدام:</b> تقدّمك في الدروس، وآخر صفحة قرأتها، والجلسات المحجوزة.</li><li><b>بيانات الأجهزة والدخول:</b> نوع الجهاز والمتصفح وعنوان IP وأوقات تسجيل الدخول، ونستخدمها لتطبيق حد الجهازين وحماية حسابك من المشاركة أو الاختراق.</li><li><b>ما ترسله لنا:</b> رسائل التواصل والتقييمات وما تشاركه في الجلسات.</li></ul>"),
 ("٣) ما لا نجمعه", "<p><b>لا نحفظ بيانات البطاقات البنكية ولا أرقام المحافظ.</b> تُعالج المدفوعات بالكامل لدى Paymob أو البنك الأهلي المصري أو PayPal، ونستقبل منهم فقط نتيجة العملية.</p>"),
 ("٤) كيف نستخدم بياناتك", "<ul><li>إنشاء حسابك وفتح الأدوات التي اشتريتها.</li><li>معالجة المدفوعات والاشتراكات المتجددة وإصدار الفواتير.</li><li>إرسال تأكيدات الطلبات وبيانات الدخول وتذكيرات الجلسات وتجديد الاشتراك.</li><li>حفظ تقدّمك وتحسين تجربة التعلّم.</li><li>حماية المحتوى: العلامة المائية باسم الحساب، ورصد الدخول من أجهزة متعددة أو المشاركة غير المصرح بها.</li><li>إرسال النشرة البريدية والعروض <b>فقط بموافقتك</b>، ويمكنك إلغاء الاشتراك من أي رسالة.</li><li>الالتزام بالمتطلبات القانونية والضريبية.</li></ul>"),
 ("٥) مشاركة البيانات", "<p>لا نبيع بياناتك ولا نؤجرها. نشاركها بالحد الأدنى اللازم مع مزوّدي خدمات يعملون لصالحنا: بوابات الدفع، وخدمة الاستضافة، وخدمة بث الفيديو المحمي (Bunny)، وخدمة إرسال البريد، ومنصة الاجتماعات (Zoom أو Google Meet)، وأدوات التحليلات. وقد نفصح عنها للجهات الرسمية إذا طلب القانون ذلك، أو لحماية حقوقنا عند ثبوت إساءة استخدام المحتوى.</p>"),
 ("٦) ملفات تعريف الارتباط (الكوكيز)", "<p>نستخدم كوكيز ضرورية لتسجيل الدخول والسلة، وكوكيز تحليلية لتحسين الموقع، وكوكيز تسويقية فقط بعد موافقتك. يمكنك التحكم فيها من إعدادات متصفحك.</p>"),
 ("٧) مدة الاحتفاظ", "<p>نحتفظ ببيانات الحساب طالما الحساب نشط، وبسجلات الطلبات والفواتير المدة التي يتطلبها القانون. عند طلب حذف الحساب نحذف بياناتك أو نجعلها مجهولة الهوية خلال ٣٠ يوماً، عدا ما يلزمنا القانون بحفظه.</p>"),
 ("٨) حماية البيانات", "<p>اتصال مشفّر (HTTPS)، وكلمات مرور مشفّرة، ووصول محدود لفريق العمل، وفيديوهات تُبث بروابط مؤقتة محمية.</p>"),
 ("٩) حقوقك", f"<ul><li>الاطلاع على بياناتك والحصول على نسخة منها.</li><li>تصحيحها من «حسابي ← بياناتي».</li><li>طلب حذف حسابك وبياناتك.</li><li>سحب موافقتك على الرسائل التسويقية في أي وقت.</li></ul><p>لممارسة أي حق راسلنا على <span class='copyable'>{MAIL}</span>، ونرد خلال ١٤ يوماً.</p>"),
 ("١٠) الأطفال", "<p>المنصة غير موجّهة لمن هم دون ١٨ عاماً، ولا نجمع بياناتهم عن قصد دون موافقة ولي الأمر.</p>"),
 ("١١) التحديثات", "<p>قد نحدّث هذه السياسة، ونُبلغك بالتغييرات الجوهرية على بريدك أو داخل حسابك.</p>"),
]),
("refund.html", "سياسة الاسترداد والإلغاء", "سياسة عدم الاسترداد، والحالات المستثناة، وإلغاء الاشتراكات، وتغيير مواعيد الجلسات على منصة د. مرفت سرور.", [
 ("ملخص سريع", "<div class='alert info'><ul style='margin:0'><li><b>كل المبيعات نهائية:</b> لا استرداد للأدوات أو الكورسات أو الكتب أو الاشتراكات بعد الشراء.</li><li><b>استثناءات:</b> الخصم المزدوج، والخطأ التقني الذي لم يُحل، وإلغاء الجلسة من جهتنا.</li><li><b>استيقظ VIP:</b> يمكنك إلغاء التجديد في أي وقت، ويبقى الوصول حتى نهاية الفترة المدفوعة.</li><li><b>الجلسات:</b> تغيير الموعد مجاناً حتى ٢٤ ساعة قبل الجلسة.</li></ul></div>"),
 ("١) عدم القابلية للاسترداد", "<p>لأن الأدوات رقمية وتُفتح في حسابك فور الدفع، فإن <b>كل عمليات الشراء نهائية</b>، ولا يمكن استرداد المبالغ أو استبدال الأدوات أو الاشتراكات أو جزء منها لأي سبب، بما في ذلك:</p><ul><li>الشراء عن طريق الخطأ.</li><li>عدم قراءة وصف الأداة أو محتواها قبل الشراء.</li><li>عدم المتابعة أو المشاهدة خلال مدة الاشتراك.</li><li>عدم تحقق النتيجة أو الفائدة المتوقعة.</li><li>تغيّر الظروف الشخصية بعد الشراء.</li></ul><p>لذلك نوفر وصفاً تفصيلياً لكل أداة ومحتواها قبل الشراء، ويمكنك سؤالنا عن أي تفصيل قبل الدفع.</p>"),
 ("٢) الحالات المستثناة", "<ul><li><b>الخصم المزدوج:</b> إذا خُصم المبلغ مرتين لنفس الطلب، يُرد المبلغ المكرر كاملاً.</li><li><b>الخطأ التقني:</b> إذا دفعت ولم تُفتح الأداة في حسابك، أو واجهت مشكلة تقنية من جهتنا تمنع الوصول ولم نتمكن من حلها خلال ٧ أيام عمل من إبلاغنا، نعيد المبلغ أو نفتح لك أداة بديلة بنفس القيمة بحسب رغبتك.</li><li><b>إلغاء الجلسة من جهتنا:</b> إذا ألغت د. مرفت جلسة فردية، نعيد جدولتها في موعد تختاره أو نرد مبلغها كاملاً.</li></ul>"),
 ("٣) اشتراك برنامج استيقظ VIP", "<ul><li>الاشتراك يتجدد تلقائياً في نهاية كل فترة بنفس وسيلة الدفع.</li><li>يمكنك إلغاء التجديد التلقائي في أي وقت من «حسابي ← اشتراكاتي»، ويبقى وصولك حتى نهاية الفترة المدفوعة.</li><li>لا يُسترد مبلغ الفترة الجارية أو جزء منها بعد بدايتها.</li><li>نرسل تذكيراً قبل تجديد الاشتراك السنوي بـ ٧ أيام على الأقل، حتى تقرر قبل الخصم.</li><li>الأدوات التي اشتريتها منفصلة تبقى لك بعد انتهاء الاشتراك.</li></ul>"),
 ("٤) الجلسات الفردية", "<ul><li>يمكن تغيير موعد الجلسة مجاناً حتى ٢٤ ساعة قبلها من حسابك أو بالتواصل معنا.</li><li>عدم الحضور، أو طلب التغيير خلال أقل من ٢٤ ساعة، يُعتبر جلسة مستخدمة ولا يُرد مبلغها.</li><li>التأخير يُخصم من وقت الجلسة ولا تُمدّد.</li><li>باقة الجلسات لا يُسترد مبلغها، ويجب استخدامها خلال ٩٠ يوماً من الشراء.</li></ul>"),
 ("٥) الإهداء", "<p>الأدوات المُهداة لا يُسترد مبلغها ولا تُنقل إلى شخص آخر بعد فتحها في حساب المُهدى إليه.</p>"),
 ("٦) إلغاء الحساب بسبب المخالفة", "<p>عند إيقاف الحساب بسبب مشاركة المحتوى أو بيانات الدخول أو أي مخالفة لـ<a href='terms.html'>الشروط والأحكام</a>، لا يحق للمشترك استرداد أي مبلغ.</p>"),
 ("٧) كيف تقدّم طلب استرداد في الحالات المستثناة", f"<ol><li>راسلنا على <span class='copyable'>{MAIL}</span> أو واتساب <span class='copyable'>{PHONE}</span>.</li><li>اذكر رقم الطلب (يبدأ بـ MS-) والبريد المسجل، وأرفق إثبات الدفع.</li><li>نرد خلال يومي عمل بقبول الطلب أو سبب رفضه.</li></ol>"),
 ("٨) مدة وطريقة رد المبلغ", "<ul><li>يُرد المبلغ بنفس وسيلة الدفع الأصلية.</li><li>البطاقات: من ٥ إلى ١٤ يوم عمل حسب البنك.</li><li>PayPal: من ٣ إلى ٥ أيام عمل.</li><li>المحافظ الإلكترونية: من ٣ إلى ٧ أيام عمل.</li><li>فوري: تحويل إلى محفظة أو حساب بنكي تحدده خلال ٧ أيام عمل.</li><li>رسوم البنوك وتحويل العملة لا تُسترد لأنها خارج تحكمنا.</li></ul>"),
]),
("delivery.html", "سياسة تقديم الخدمة", "كيف ومتى تحصل على الأدوات والاشتراكات والجلسات بعد الدفع.", [
 ("١) طبيعة الخدمات", "<p>كل منتجات المنصة <b>رقمية أو خدمات أونلاين</b>، ولا يوجد أي منتج يُشحن، ولا توجد رسوم شحن.</p>"),
 ("٢) الأدوات الرقمية (كورسات، تمارين، كتب)", "<ul><li>تُفتح فوراً في حسابك بعد تأكيد الدفع، عادة خلال دقائق.</li><li>تصلك رسالة على بريدك بتأكيد الطلب ورابط الدخول.</li><li>تجد كل ما اشتركت فيه في «حسابي ← اشتراكاتي».</li><li>تُبث التسجيلات وتُقرأ الكتب داخل المنصة فقط، ولا تتوفر للتحميل.</li><li>الوصول من جهازين كحد أقصى في نفس الوقت.</li></ul>"),
 ("٣) الدفع عبر فوري أو أمان", "<p>تحصل على رقم مرجعي صالح لمدة ٤٨ ساعة. بعد السداد في المنفذ تُفتح الأداة تلقائياً. إذا لم يُسدَّد المبلغ خلال المدة يُلغى الطلب.</p>"),
 ("٤) برنامج استيقظ VIP", "<p>يُفعَّل فوراً بعد الدفع ويُفتح كل المحتوى المشمول. تصلك مواعيد اللقاءات المباشرة وروابطها على البريد وفي حسابك، ويُتاح التسجيل لاحقاً لمن فاته اللقاء خلال مدة الاشتراك.</p>"),
 ("٥) الجلسات الفردية", "<ul><li>بعد الدفع يصلك تأكيد الحجز بالموعد بتوقيت بلدك.</li><li>يصلك رابط الجلسة (Zoom أو Google Meet) على البريد وفي حسابك.</li><li>تذكير قبل الجلسة بـ ٢٤ ساعة وقبلها بساعة.</li></ul>"),
 ("٦) المتطلبات التقنية", "<p>اتصال إنترنت مستقر، ومتصفح حديث على الهاتف أو الكمبيوتر. للجلسات: كاميرا وميكروفون.</p>"),
 ("٧) إذا لم تصلك الأداة", f"<ol><li>تأكد من تسجيل الدخول بنفس البريد المستخدم في الشراء.</li><li>راجع مجلد الرسائل غير المرغوبة.</li><li>إذا مرت ساعة دون ظهور الأداة، راسلنا على <span class='copyable'>{MAIL}</span> أو واتساب <span class='copyable'>{PHONE}</span> برقم الطلب.</li></ol>"),
 ("٨) الفواتير", "<p>تجد فاتورة كل طلب في «حسابي ← الطلبات والفواتير»، وتصلك نسخة على البريد.</p>"),
]),
]
